mapper.select:
SELECT id, run_key, job_type, state, planned_shards, succeeded_shards, failed_shards, version
FROM job_run
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND run_key=#{runKey} FOR UPDATE

SELECT id, run_key, job_type, state, planned_shards, succeeded_shards, failed_shards, version
FROM job_run
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{runId} FOR UPDATE

mapper.update:
UPDATE job_run
SET state=#{state}, planned_shards=#{plannedShards}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{runId}
AND version=#{version}

UPDATE job_run
SET succeeded_shards=succeeded_shards+#{succeededDelta}, failed_shards=failed_shards+#{failedDelta}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{runId}

mapper.select:
SELECT shard_key
FROM job_shard
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND run_id=#{runId}

SELECT id, run_id, job_type, shard_key, state, lease_owner, lease_until, claim_epoch, fence_token, cursor_key, retry_count, version
FROM job_shard
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId} FOR UPDATE

SELECT id, run_id, job_type, shard_key, state, lease_owner, lease_until, claim_epoch, fence_token, cursor_key, retry_count, version
FROM job_shard
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND job_type=#{jobType}
AND state='READY'
AND (next_retry_at IS NULL OR next_retry_at<=#{now})
ORDER BY id
LIMIT 1 FOR UPDATE

mapper.update:
UPDATE job_shard
SET state='LEASED', lease_owner=#{owner}, lease_until=#{leaseUntil}, claim_epoch=claim_epoch+1, fence_token=#{fence}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId}
AND version=#{version}
AND state='READY'

UPDATE job_shard
SET lease_until=#{leaseUntil}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId}
AND claim_epoch=#{epoch}
AND fence_token=#{fence}
AND state='LEASED'

UPDATE job_shard
SET cursor_key=#{cursor}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId}
AND claim_epoch=#{epoch}
AND fence_token=#{fence}
AND state='LEASED'

UPDATE job_shard
SET state=#{state}, lease_owner=NULL, lease_until=NULL, fence_token=NULL, last_error=#{error}, retry_count=retry_count+#{retryDelta}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId}
AND claim_epoch=#{epoch}
AND fence_token=#{fence}
AND state='LEASED'

mapper.select:
SELECT id, run_id, claim_epoch, fence_token, version
FROM job_shard
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND state='LEASED'
AND lease_until<#{now}
ORDER BY id
LIMIT #{limit} FOR UPDATE

mapper.update:
UPDATE job_shard
SET state='READY', lease_owner=NULL, lease_until=NULL, fence_token=NULL, claim_epoch=claim_epoch+1, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{shardId}
AND version=#{version}
AND state='LEASED'

mapper.select:
SELECT id, run_key, job_type, state, planned_shards, succeeded_shards, failed_shards, version, created_at
FROM job_run
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

SELECT id, shard_key, state, lease_owner, lease_until, claim_epoch, last_error
FROM job_shard
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND run_id=#{runId}
ORDER BY shard_key
